import React, { createContext, useContext, useEffect, useState, ReactNode } from 'react';
import { 
  User, 
  signInWithEmailLink, 
  isSignInWithEmailLink,
  sendSignInLinkToEmail,
  signOut, 
  onAuthStateChanged
} from 'firebase/auth';
import { auth } from '../config/firebase';

interface AuthContextType {
  currentUser: User | null;
  sendMagicLink: (email: string) => Promise<void>;
  completeSignIn: () => Promise<void>;
  logout: () => Promise<void>;
  loading: boolean;
  magicLinkSent: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

interface AuthProviderProps {
  children: ReactNode;
}

export function AuthProvider({ children }: AuthProviderProps) {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [magicLinkSent, setMagicLinkSent] = useState(false);

  // Check if user is returning from magic link
  useEffect(() => {
    if (isSignInWithEmailLink(auth, window.location.href)) {
      // User clicked magic link, complete sign in
      completeSignIn();
    }
  }, []);

  async function sendMagicLink(email: string) {
    try {
      const actionCodeSettings = {
        url: window.location.origin + '/dashboard',
        handleCodeInApp: true,
      };

      await sendSignInLinkToEmail(auth, email, actionCodeSettings);

      // Save email to localStorage for later use
      window.localStorage.setItem('emailForSignIn', email);

      setMagicLinkSent(true);
      console.log('Magic link sent successfully');
    } catch (error: any) {
      console.error('Error sending magic link:', error);
      throw new Error('Failed to send magic link. Please try again.');
    }
  }

  async function completeSignIn() {
    try {
      const email = window.localStorage.getItem('emailForSignIn');
      if (!email) {
        throw new Error('No email found. Please try signing in again.');
      }

      await signInWithEmailLink(auth, email, window.location.href);

      // Clear email from localStorage
      window.localStorage.removeItem('emailForSignIn');

      // User is now signed in
      console.log('Sign in completed successfully');

      // Redirect to dashboard if not already there
      if (window.location.pathname !== '/dashboard') {
        window.location.href = '/dashboard';
      }
    } catch (error: any) {
      console.error('Error completing sign in:', error);
      throw new Error('Failed to complete sign in. Please try again.');
    }
  }

  async function logout() {
    return signOut(auth);
  }

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setCurrentUser(user);
      setLoading(false);
    });

    return unsubscribe;
  }, []);

  const value = {
    currentUser,
    sendMagicLink,
    completeSignIn,
    logout,
    loading,
    magicLinkSent
  };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
}
